/bin/zsh -lc "python3 - <<'PY'
import zipfile,xml.etree.ElementTree as E,glob
for p in sorted(glob.glob('docs/kiertokirjeet/*.docx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  r=E.fromstring(z.read('word/document.xml'))
  for v in r.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
   print(''.join(t.text or '' for t in v.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t')))
for p in sorted(glob.glob('docs/liitteet/*.xlsx')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  for n in z.namelist():
   if n=='xl/workbook.xml' or n=='xl/sharedStrings.xml' or n.startswith('xl/worksheets/sheet') and n.endswith('.xml'):
    print(n,z.read(n).decode())
PY"

